import type { AbilityUpgradeEffect, Card, CardRarity } from './data';

/** Original fictional characters; catalog rarity never modifies combat stats. */
export const CELLBLOCK_WAVE = [
  ['inmate-crafty', 'Inmate Crafty', 'Uncommon', 'Normal', 2, 3, 'Make Do', 'On Reveal: If another friendly inmate or a friendly support card is here, gain +3 Hands.', 'Growth'],
  ['inmate-boyfriend', 'Inmate Boyfriend', 'Rare', 'Light', 3, 4, 'Looking Out', 'On Reveal: Give your weakest other ally here +3 Hands. Also give your weakest friendly Cellblock character in another district +3 Hands.', 'Support'],
  ['inmate-informant', 'Inmate Informant', 'Rare', 'Dark', 3, 4, 'Quiet Tip', 'On Reveal: Give the strongest enemy here -3 Hands. Protection and immunity can block this.', 'Disruption'],
