sources.lib/squabblemon-engine/src/characterWave:
import type { AbilityUpgradeEffect, Card, CardRarity } from './data';

/** Stable collection IDs: balance updates never replace owned cards or cosmetics. */
export const CHARACTER_WAVE = [
  ['homelessguy', 'homeless-guy', 'Homeless Guy', 'Mythical', 'Normal', 3, 4, 'Nothing to Lose', 'On Reveal: Choose 0–4 extra Motion; gain that many Hands, plus 1 if you invested any Motion. If the deployment cost alone spent your last Motion, instead steal up to 2 Hands from the strongest enemy here.', 'Growth'],
  ['fangirl', 'fangirl', 'Fangirl', 'SuperCommon', 'Light', 1, 1, 'Day One', 'On Reveal: Your strongest other ally here becomes your idol. Ongoing: The first time your idol gains Hands each round, gain +1 Hand.', 'Support'],
  ['grownfanboy', 'grown-man-fanboy', 'Grown-Man Fanboy', 'Epic', 'Normal', 3, 4, 'He Doesn’t Know You', 'On Reveal: Your strongest other ally becomes your idol. Ongoing: Intercept the first hostile ability targeting your idol each round. If Fangirl is here when you take the hit, gain +2 Hands.', 'Support'],
  ['lawlessyn', 'lawless-yn', 'Lawless YN', 'Rare', 'Dark', 2, 2, 'Wrong Block', 'On Reveal: Move the weakest enemy here to their strongest other open district. If it moves, Lawless YN gains +1 Hand. Protection, immunity and movement locks can stop this.', 'Disruption'],
  ['streetapostle', 'street-apostle', 'The Street Apostle', 'Epic', 'Plant', 3, 3, 'Spread the Word', 'Ongoing: The first time another Plant ally gains Hands each round, repeat up to 2 of that gain onto your weakest Plant ally in each other district. Copied gains cannot trigger this again.', 'Growth'],
  ['asphaltapostle', 'asphalt-apostle', 'The Asphalt Apostle', 'Epic', 'Earth', 3, 4, 'Concrete Congregation', 'On Reveal: Protect your weakest other Earth ally anywhere and give it +1 Hand. Ongoing: Once per round, block the first hostile forced move against an Earth ally; give that ally +2 Hands instead.', 'Support'],
  ['colognecriminal', 'cologne-criminal', 'Cologne Criminal', 'Epic', 'Poison', 3, 3, 'You Can Still Smell Him', 'On Reveal: Leave Lingering Scent here through the end of next round. The first enemy entering this district each round gets 2 Burn, even if moved here. Scent stays after you leave.', 'Disruption'],
  ['passportbro', 'passport-bro', 'Passport Bro', 'Epic', 'Water', 3, 3, 'Geographic Arbitrage', 'On Reveal: Move your weakest other ally here to your weakest other open district. Ongoing: Once per round, when another Water ally leaves a district you are losing, cleanse it and give it +2 Hands.', 'Movement'],
  ['seafoodassassin', 'seafood-assassin', 'Seafood Assassin', 'Legendary', 'Poison', 4, 3, 'Extra Sauce', 'On Reveal: Apply 2 Burn to every enemy here, then immediately detonate all their Burn as Hands damage and consume it. Protection blocks the whole hit.', 'Disruption'],
  ['homelesslegend', 'homeless-legend', 'Homeless Legend', 'Legendary', 'Plant', 4, 5, 'Built Different', 'Ongoing: Survive your first lethal Hands reduction at 1 Hand. At round end, recover up to 2 Hands lost to damage.', 'Sustain'],
  ['godofhookah', 'god-of-hookah', 'God of Hookah', 'Mythical', 'Poison', 4, 4, 'Pass the Hose', 'Ongoing: At round end, the first enemy damaged by Burn in each district passes 1 Burn to the weakest unburned enemy in the next district. New Burn waits until next round.', 'Disruption'],
  ['mailman', 'the-mailman', 'The Mailman', 'Mythical', 'Electric', 3, 3, 'Express Delivery', 'Ongoing: Your second Electric character played each round sends a Package to your weakest other open district. The next Electric character played there costs 1 less Motion and gains +2 Hands. Only one Package can be pending.', 'Support'],
] as const;

export const characterWaveUpgradeEffects: Record<string, readonly AbilityUpgradeEffect[]> = Object.fromEntries(
  CHARACTER_WAVE.map(([engineId]) => [engineId, [0, 1, 2].map(() => ({ kind: 'self-power' as const, amount: 1 as const, trigger: 'base-success' as const }))]),
);
export const characterWaveRarities: Record<string, CardRarity> = Object.fromEntries(CHARACTER_WAVE.map(([engineId, , , rarity]) => [engineId, rarity]));
export const characterWaveCards: Record<string, Card> = Object.fromEntries(CHARACTER_WAVE.map(
  ([engineId, id, name, , type, cost, power, ability, effect, role]) => [engineId, {
    id, name, type, cost, power, ability, effect, kind: 'character', roles: [role],
    abilityUpgrades: [2, 5, 8].map((unlockLevel, index) => ({
      id: engineId + ':upgrade:' + (index + 1), name: ability + ' ' + ['Practice', 'Confidence', 'Mastery'][index],
      description: 'The first time the base ability succeeds this match, gain +1 Hand.', unlockLevel,
      effect: characterWaveUpgradeEffects[engineId][index],
    })),
  }],
));

sources.lib/squabblemon-engine/src/commonCards.t:
import type { AbilityUpgradeEffect, Card } from './data';

/** Neighborhood Commons: inexpensive bodies and straightforward support effects. */
const definitions = [
  ['youngbull', 'young-bull', 'Young Bull', 'Fire', 2, 2, 'Step Up', 'On Reveal: Gain +1 Hand. If an enemy is here, also apply 1 Burn to the highest-Hands enemy here.', 'Pressure'],
  ['transplant', 'racially-ambiguous-transplant', 'Racially Ambiguous Transplant', 'Air', 1, 1, 'New Here', 'If you have no other cards here, gain +1 Hands.', 'Opener'],
  ['tayaty', 'bad-lil-cousin-tayaty', 'Bad Lil Cousin Tayaty', 'Fire', 1, 1, 'Act Up', 'On Reveal: Echo the last On Reveal ability that resolved this round. Gain +1 Hand.', 'Combo'],
  ['edgar', 'edgar', 'Edgar', 'Normal', 2, 2, 'Gang Check', 'If another friendly card costing 2 or less is here, gain +1 Hands.', 'Pressure'],
  ['nguyen', 'nguyen', 'Nguyen', 'Electric', 2, 2, 'Side Project', 'If you have a friendly card in another district, gain +1 Hands.', 'Tempo'],
  ['manman', 'man-man', 'Man-Man', 'Earth', 3, 3, 'All Hands', 'If at least two other friendly cards are here, gain +2 Hands.', 'Pressure'],
  ['pinaynurse', 'pinay-nurse', 'Pinay Nurse', 'Light', 2, 3, 'Check In', 'Give your lowest-Hands other ally here +3 Hands and cleanse its freeze and silence.', 'Support'],
  ['honestthot', 'honest-thot', 'Honest Thot', 'Air', 1, 2, 'Air Bond', 'Ongoing: While Honest Thot is in your hand, your other Air characters gain +1 Hand at round end.', 'Sustain', 'Air'],
  ['earthy', 'earthy-sugar-foot', 'Earthy Sugar Foot', 'Plant', 1, 1, 'Grounded', 'Give your lowest-Hands other card here +1 Hands.', 'Support'],
  ['abuela', 'abuela', 'Abuela', 'Light', 4, 4, 'Light Bond', 'Ongoing: While Abuela is in your hand, your other Light characters gain +1 Hand at round end.', 'Sustain', 'Light'],
  ['icecream', 'ice-cream-truck', 'Ice Cream Truck', 'Water', 3, 3, 'Water Bond', 'Ongoing: While Ice Cream Truck is in your hand, your other Water characters gain +1 Hand at round end.', 'Sustain', 'Water'],
] as const;

export const neighborhoodCommonIds = definitions.map(([id]) => id);
export const commonUpgradeEffects: Record<string, readonly AbilityUpgradeEffect[]> = Object.fromEntries(
  neighborhoodCommonIds.map(id => [id, [0, 1, 2].map(() => ({ kind: 'self-power' as const, amount: 1 as const, trigger: 'base-success' as const }))]),
);
export const neighborhoodCommons: Record<string, Card> = Object.fromEntries(definitions.map(
  ([engineId, id, name, type, cost, power, ability, effect, role, elementalBond]) => [engineId, {
    id, name, type, cost, power, ability,
    effect: /^(On Reveal|Ongoing):/.test(effect) ? effect : `On Reveal: ${effect}`,
    roles: [role],
    ...(elementalBond ? { elementalBond } : {}),
    abilityUpgrades: [2, 5, 8].map((unlockLevel, index) => ({
      id: `${engineId}:upgrade:${index + 1}`, name: `${ability} ${['Practice', 'Confidence', 'Mastery'][index]}`,
      description: elementalBond
        ? 'While this card is in your hand, one bonded ally gains an additional +1 Hand at round end.'
        : 'After the base ability succeeds, this card gains +1 Hands.',
      unlockLevel, effect: commonUpgradeEffects[engineId][index],
    })),
  }],
));

sources.lib/squabblemon-engine/src/continuousPow:
import { squabblehouseStaffCardIds } from './squabblehouseWave';

export const CONTINUOUS_POWER_DEPARTURES: unique symbol = Symbol('squabblemon.continuous-power-departures');

type ContinuousPowerCard = {
  readonly instanceId: string;
  readonly cardId: string;
  readonly owner: 'player' | 'cpu';
  readonly kind?: string;
  readonly hazard?: boolean;
  readonly basePower: number;
  readonly powerModifier: number;
  readonly copiedAbilityCardId?: string;
  readonly continuousPower?: number;
  readonly statuses: { readonly frozen: boolean; readonly silenced: boolean; readonly weakened: boolean };
};

type ContinuousPowerMatch<TCard extends ContinuousPowerCard> = {
  readonly boards: readonly (readonly TCard[])[];
  readonly timedEffects?: readonly { readonly targetInstanceId?: string }[];
  readonly [CONTINUOUS_POWER_DEPARTURES]?: readonly TCard[];
};

const isCharacter = (card: ContinuousPowerCard) =>
  !card.hazard && (card.kind ?? 'character') === 'character';

export const rawCombatPower = (card: ContinuousPowerCard): number =>
  card.hazard ? 0 : Math.max(0, card.basePower + card.powerModifier + (card.continuousPower ?? 0));

/** Reconciles the replay-safe Manager aura without touching unaffected card references. */
export function syncContinuousPower<TCard extends ContinuousPowerCard, TMatch extends ContinuousPowerMatch<TCard>>(
  match: TMatch,
): TMatch {
  let result = match;
  for (;;) {
    const cards = result.boards.flat();
    const managers = cards.filter(card => (card.copiedAbilityCardId ?? card.cardId) === 'squabble-house-manager' && isCharacter(card)
      && !card.statuses.frozen && !card.statuses.silenced && !card.statuses.weakened);
    if (!managers.length && !cards.some(card => card.continuousPower !== undefined)) return result;
    const counts = new Map<string, number>();
    for (const manager of managers) {
      const bonus = cards.filter(card => card.owner === manager.owner && card.instanceId !== manager.instanceId
        && isCharacter(card) && squabblehouseStaffCardIds.has(card.cardId)).length;
      if (bonus) counts.set(manager.instanceId, (counts.get(manager.instanceId) ?? 0) + bonus);
    }
    let changed = false;
    const expiredAuraDeaths: TCard[] = [];
    const boards = result.boards.map(lane => {
      let laneChanged = false;
      const next = lane.map(card => {
        const power = counts.get(card.instanceId);
        if (card.continuousPower === power) return card;
        laneChanged = true;
        changed = true;
        const updated = power === undefined
          ? (() => {
            const { continuousPower: _continuousPower, ...withoutContinuousPower } = card;
            return withoutContinuousPower as TCard;
          })()
          : { ...card, continuousPower: power };
        if ((card.continuousPower ?? 0) > (power ?? 0) && rawCombatPower(card) > 0
          && rawCombatPower(updated) === 0) expiredAuraDeaths.push(card);
        return updated;
      });
      return laneChanged ? next : lane;
    });
    if (!changed) return result;
    result = { ...result, boards } as TMatch;
    if (!expiredAuraDeaths.length) return result;
    const dead = new Set(expiredAuraDeaths.map(card => card.instanceId));
    result = {
      ...result,
      [CONTINUOUS_POWER_DEPARTURES]: [
        ...(result[CONTINUOUS_POWER_DEPARTURES] ?? []),
        ...expiredAuraDeaths,
      ],
      boards: result.boards.map(lane => {
        const remaining = lane.filter(card => !dead.has(card.instanceId));
        return remaining.length === lane.length ? lane : remaining;
      }),
      ...(result.timedEffects ? { timedEffects: result.timedEffects.filter(effect =>
        !effect.targetInstanceId || !dead.has(effect.targetInstanceId)) } : {}),
    } as TMatch;
  }
}

