    JSON.stringify(
      before.boards.map((cs) =>
        cs.map((c) => [c.instanceId, c.lane, c.powerModifier, c.statuses]),
      ),
    ) !==
      JSON.stringify(
        m.boards.map((cs) =>
          cs.map((c) => [c.instanceId, c.lane, c.powerModifier, c.statuses]),
        ),
