    const player = getLaneScoreForMatch(match, cardsInLane.filter((c) => c.owner === "player"), i as Lane, "player");
    const cpu = getLaneScoreForMatch(match, cardsInLane.filter((c) => c.owner === "cpu"), i as Lane, "cpu");
