const ELEMENTAL_MATCHUP_BONUS: Record<string, Record<string, number>> = {
  Fire: { Plant: 1 },
  Plant: { Water: 1 },
  Water: { Fire: 1 },
  Electric: { Water: 1 },
  Air: { Electric: 1 },
  Earth: { Electric: 1 },
  Light: { Dark: 1 },
  Dark: { Light: 1 },
