      burnSource: { instanceId: source.instanceId, owner: source.owner },
      statuses: { ...c.statuses, burnStacks: (c.statuses.burnStacks ?? 0) + stacks + bonus },
      lastEffectNote: note + (bonus ? ' (+' + bonus + ' elemental bonus)' : ''),
    }));
