  if (!lanes.length) return { match: m };
  const seed = JSON.stringify(['demario-mushroom', source.instanceId, source.owner, m.round, draw,
    m.nextEventSequence, m.boards.map(items => items.map(card => card.instanceId)), m.districtSnapshot]);
  const lane = lanes[seededIndex(seed, lanes.length)];
  const before = m;
  m = summonCard(m, source.owner, lane, DEMARIO_MUSHROOM, 'demario-mushroom', source);
  const token = m.boards[lane].at(-1)!;
  if (log) m = addEvent(before, m, { type: 'ability', sourceId: source.instanceId, owner: source.owner,
    lane, targetIds: [token.instanceId], note: `Special Delivery: Mushroom sprouted in district ${lane + 1} while Demario was in hand.` });
  m = fairytaleArrival(m, token.instanceId);
  m = applyScentEntry(m, token.instanceId);
  return { match: m, token };
}
function spawnHandDemarioMushrooms(match: Match, log: boolean): Match {
  let m = match;
  for (const owner of ['player', 'cpu'] as Owner[]) {
    const source = (owner === 'player' ? m.playerHand : m.cpuHand)
      .find(card => card.cardId === 'demario' && activeAbility(card));
    if (source) m = plantDemarioMushroom(m, source, 0, log).match;
  }
  return m;
}
const smileBombSeed = (match: Match, id: string, draw: number) =>
  JSON.stringify([id, draw, match.round, match.nextEventSequence, match.districtSnapshot,
    match.boards.map(lane => lane.map(card => [card.instanceId, rawCombatPower(card)]))]);

const buddySeed = (match: Match, source: CardInstance) => JSON.stringify([
  'buddy-buds', source.instanceId, match.round,
  match.boards.map(lane => lane.map(card => card.instanceId).sort()),
  match.districtSnapshot,
]);

const buddyTimedEffect = (match: Match, source: CardInstance, target: CardInstance, amount: number): Match => {
  const expiresAtRound = source.buddyEarthExpiresAtRound ?? match.round + 2;
  const effect: TimedEffect = {
    id: `buddy-earth:${source.instanceId}:${target.instanceId}:${match.round}:${amount}`,
    kind: amount > 0 ? 'buddy-earth-buff' : 'buddy-earth-debuff',
    sourceInstanceId: source.instanceId,
    targetInstanceId: target.instanceId,
    owner: source.owner,
    lane: target.lane ?? source.lane!,
    startsAtRound: match.round,
    expiresAtRound,
    expiration: 'round-start',
    amount,
  };
  return { ...match, timedEffects: [...match.timedEffects.filter(item => item.id !== effect.id), effect] };
};

const applyBuddyEarthToTarget = (match: Match, source: CardInstance, target: CardInstance): Match => {
  if (target.hazard || target.owner === source.owner && canonicalElement(target.type) !== 'Earth') return match;
  if (target.owner === source.owner) {
    const before = findCard(match, target.instanceId);
    if (!before) return match;
    const after = modify(match, target.instanceId, card => ({
      ...card, powerModifier: card.powerModifier + 2, lastEffectNote: 'Earth Squabble: +2 Hands for two rounds.',
    }));
    return buddyTimedEffect(after, source, findCard(after, target.instanceId)!, 2);
  }
  const before = findCard(match, target.instanceId);
  if (!before) return match;
  const after = targetEnemyPowerReduction(match, source, before, -1, 'Earth Squabble: -1 Hand for two rounds.');
  const changed = findCard(after, target.instanceId);
  if (!changed || directDamageAmount(match, after, before) <= 0) return after;
  return buddyTimedEffect(after, source, changed, -1);
};

const applyBuddyEarthToBoard = (match: Match, source: CardInstance): Match => {
  let result = match;
  const targets = result.boards.flat().sort((a, b) => a.instanceId.localeCompare(b.instanceId));
  for (const target of targets) {
    const currentSource = findCard(result, source.instanceId);
    const currentTarget = findCard(result, target.instanceId);
    if (currentSource && currentTarget) result = applyBuddyEarthToTarget(result, currentSource, currentTarget);
  }
  return result;
};

const plantBuddyBuds = (match: Match, source: CardInstance): Match => {
  const sproutsAtRound = match.round + 2;
  const seed = buddySeed(match, source);
  let result = modify(match, source.instanceId, card => ({
    ...card, buddyForm: 'earth', buddyGrowthAtRound: sproutsAtRound,
    lastEffectNote: `Buddy Buds: +3 Hands and Buds sprout after two rounds (Round ${sproutsAtRound}).`,
  }));
  // A Bud can sprout on the final round's start and reward cards already there,
  // but one scheduled beyond the match limit would never have a payoff.
  if (sproutsAtRound > getMatchRoundLimit(match)) return modify(result, source.instanceId, card => ({
    ...card, lastEffectNote: `Buddy Bud planting skipped: they would sprout after the match ends (delayed +3 Hands in Round ${sproutsAtRound}).`,
  }));
  const eligible = ([0, 1, 2] as Lane[]).filter(laneIndex =>
    !getStoryLockedLanes(result, source.owner).includes(laneIndex) && inLane(result, source.owner, laneIndex).length < 4);
  if (!eligible.length) return modify(result, source.instanceId, card => ({
    ...card, lastEffectNote: `Buddy Bud planting skipped: all districts are full or locked (delayed +3 Hands in Round ${sproutsAtRound}).`,
  }));
  const wanted = Math.min(eligible.length, 2 + seededIndex(`${seed}:count`, 2));
  const selected: Lane[] = [];
  let remaining = [...eligible];
  while (selected.length < wanted) {
    const index = seededIndex(`${seed}:lane:${selected.length}`, remaining.length);
    selected.push(remaining[index]);
    remaining = remaining.filter((_, candidate) => candidate !== index);
  }
  for (const laneIndex of selected) {
    const template = createCardInstance('rastamon', source.owner, 'buddy-bud', 0);
    const arrivalOrder = nextArrivalOrder(result);
    const bud: CardInstance = {
      ...template, id: 'buddy-bud', cardId: 'buddy-bud', name: 'Buddy Bud', type: 'Plant',
      cost: 0, power: 0, basePower: 0, powerModifier: 0, ability: 'Buddy Bud',
      effect: `Sprouts in Round ${sproutsAtRound}; the last eligible friendly character here gains +3 Hands.`,
      abilityUpgrades: [], kind: 'token', hazard: true, lane: laneIndex, playedRound: match.round, arrivalOrder,
      instanceId: `${source.instanceId}:bud:${match.round}:${laneIndex}`,
      buddyBud: { sourceInstanceId: source.instanceId, sproutsAtRound, sprouted: false },
      lastEffectNote: `Dormant Buddy Bud · sprouts in Round ${sproutsAtRound}.`,
    };
    result = { ...result, nextArrivalOrder: arrivalOrder + 1, boards: result.boards.map((cardsInLane, index) =>
      index === laneIndex ? [...cardsInLane, bud] : cardsInLane) as Match['boards'] };
  }
  return modify(result, source.instanceId, card => ({
    ...card, lastEffectNote: `Buddy Buds: planted ${selected.length} Bud${selected.length === 1 ? '' : 's'}; they sprout in Round ${sproutsAtRound}.`,
  }));
};

const sproutBuddyBuds = (match: Match): Match => {
  let result = match;
  for (const bud of match.boards.flat().filter(card => card.buddyBud && !card.buddyBud.sprouted
    && card.buddyBud.sproutsAtRound <= match.round)) {
    const currentBud = findCard(result, bud.instanceId);
    if (!currentBud || currentBud.lane === null) continue;
    const eligibleRecipients = result.boards[currentBud.lane].filter(card =>
      card.owner === currentBud.owner && !card.hazard && card.instanceId !== currentBud.instanceId
      && (card.kind ?? 'character') !== 'support');
    const recipient = eligibleRecipients.reduce<CardInstance | undefined>((last, card) =>
      !last || (card.arrivalOrder ?? -1) >= (last.arrivalOrder ?? -1) ? card : last, undefined);
    const beforeSprout = result;
    result = modify(result, bud.instanceId, card => ({
      ...card,
      buddyBud: { ...card.buddyBud!, sprouted: true },
      effect: 'Sprouted Buddy Bud: the last eligible friendly character in this district gains +3 Hands.',
      lastEffectNote: recipient
        ? `Buddy Bud sprouted · ${recipient.name} is the last eligible recipient.`
        : 'Buddy Bud sprouted without an eligible friendly recipient.',
    }));
    if (recipient) {
      result = modify(result, recipient.instanceId, card => ({
        ...card, powerModifier: card.powerModifier + 3,
        lastEffectNote: 'Buddy Bud sprouted: +3 Hands as the last eligible character in this district.',
      }));
      result = { ...result, boards: result.boards.map(cardsInLane =>
        cardsInLane.filter(card => card.instanceId !== bud.instanceId)) as Match['boards'] };
      result = addEvent(beforeSprout, result, { type: 'ability', sourceId: bud.buddyBud!.sourceInstanceId,
        owner: bud.owner, lane: bud.lane!, targetIds: [recipient.instanceId, bud.instanceId],
        note: `Buddy Bud sprouted and gave ${recipient.name} +3 Hands as the last eligible character in the district.` });
    }
  }
  return result;
};

const resolveBuddyGrowthAtRoundStart = (match: Match): Match => {
  let result = match;
  for (const buddy of match.boards.flat().filter(card => card.cardId === 'buddy'
    && card.buddyForm === 'earth' && card.buddyGrowthAtRound !== undefined
    && card.buddyGrowthAtRound <= match.round)) {
    const beforeGrowth = result;
    result = modify(result, buddy.instanceId, card => ({
      ...card, powerModifier: card.powerModifier + 3, buddyGrowthAtRound: undefined,
      lastEffectNote: 'Buddy Buds: delayed growth +3 Hands at the start of this round.',
    }));
    result = addEvent(beforeGrowth, result, { type: 'ability', sourceId: buddy.instanceId, owner: buddy.owner,
      lane: buddy.lane ?? undefined, targetIds: [buddy.instanceId],
      note: `Buddy Buds: BUDDY gained +3 Hands at the start of Round ${match.round}, after two rounds.` });
  }
  return result;
};

function detonateSmileBombs(match: Match): Match {
  let m = match;
  // A stable order also gives multiple KYLEs independent, reproducible kill credit.
  const due = m.boards.flat().filter(card => card.smileBomb && card.smileBomb.detonatesAtRound <= m.round)
    .sort((a, b) => a.instanceId.localeCompare(b.instanceId));
  for (const scheduled of due) {
    const bomb = findCard(m, scheduled.instanceId);
    if (!bomb?.smileBomb || bomb.lane === null) continue;
    const before = m, payload = bomb.smileBomb;
    const enemies = inLane(m, payload.sourceOwner === 'player' ? 'cpu' : 'player', bomb.lane)
      .filter(card => card.kind !== 'support').sort((a, b) => a.instanceId.localeCompare(b.instanceId));
    const target = enemies.length ? enemies[seededIndex(smileBombSeed(m, bomb.instanceId, 0), enemies.length)] : undefined;
    const source = findCard(m, payload.sourceInstanceId);
    // Always consume the fuse, even if the lane emptied or KYLE left the board.
    m = { ...m, boards: m.boards.map(lane => lane.filter(card => card.instanceId !== bomb.instanceId)) as Match['boards'] };
    let killed = false;
    let damaged = false;
    let reward = 0;
    if (target) {
      m = targetEnemyPowerReduction(m, source ?? { ...bomb, owner: payload.sourceOwner }, target, -2, 'Smile Bomb: -2 Hands.');
      killed = !findCard(m, target.instanceId);
      damaged = directDamageAmount(before, m, target) > 0;
      if (damaged && source && source.owner === payload.sourceOwner && source.lane !== null) {
        reward = killed ? 2 : 1;
        m = modify(m, source.instanceId, card => ({ ...card, powerModifier: card.powerModifier + reward,
          lastEffectNote: killed ? 'Smile Bomb knockout: +2 Hands.' : 'Smile Bomb hit: +1 Hands.' }));
      }
    }
    m = addEvent(before, m, { type: 'ability', sourceId: source?.instanceId, owner: payload.sourceOwner,
      lane: bomb.lane, kind: damaged ? 'fire' : 'blocked', targetIds: [bomb.instanceId, ...(target ? [target.instanceId] : [])],
      note: target ? damaged
        ? 'Smile Bomb hit ' + target.name + ' for -2 Hands.' + (reward ? ' KYLE gained +' + reward + ' Hands' + (killed ? ' for the knockout.' : '.') : '')
        : target.name + ' blocked the Smile Bomb.'
        : 'Smile Bomb fizzled: no enemy in its district.',
    });
    m = settleLeaderReactions(m);
  }
  return m;
}

export function nextRound(match: Match): Match {
  if (match.phase !== 'resolved') throw new Error('Round is not resolved');
  // Resolve persistent statuses and hand bonds before either advancing or scoring.
  const ordinaryRoundEnd = settleLeaderReactions(returnAliceAtRoundEnd(applyOngoingRoundEndHandEffects(applyOngoingRoundEndEffects(creativeRoundEnd(homecomingRoundEnd(applyBurntPlates(match), homecomingTools()), creativeTools())))));
  const roundEnded = settleLeaderReactions(creativeAfterAction(match,ordinaryRoundEnd,creativeTools()));
  if (match.round >= getMatchRoundLimit(match)) {
    const complete = applyStoryEffects({ ...roundEnded, phase: 'complete' as const });
    return addEvent(match, complete, { type: 'match-complete', owner: 'player', note: 'The match is complete.' });
  }
  const draw = (owner: Owner, deckId: string, deckCards: string[], index: number) =>
    index < deckCards.length ? createCardInstance(deckCards[index], owner, deckId, index) : null;
  const p = draw('player', match.playerDeck, match.playerCardIds, match.playerDrawIndex);
  const c = draw('cpu', match.cpuDeck, match.cpuCardIds, match.cpuDrawIndex);
  const next = match.round + 1;
  const expiring = roundEnded.timedEffects.filter((effect) => effect.expiresAtRound === next);
  let m: Match = {
    ...roundEnded,
    districtTraps: (roundEnded.districtTraps ?? []).filter(trap =>
      trap.kind !== 'open-tab' || trap.expiresAfterRound >= next),
    lastRevealedCardId: null,
    laneDamage: [],
    roundMovedIds: { player: [], cpu: [] },
    round: next,
    phase: 'player',
    // One unspent Motion carries forward. Passing can set up a stronger next
    // round, but the cap prevents late turns from becoming automatic.
    playerMotion: Math.min(MAX_MOTION, next + Math.min(1, roundEnded.playerMotion)),
    cpuMotion: Math.min(MAX_MOTION, next + Math.min(1, roundEnded.cpuMotion)),
    landlordTaxUsed: { player: { 0: false, 1: false, 2: false }, cpu: { 0: false, 1: false, 2: false } },
    boards: roundEnded.boards.map((items) => items.map((card) => ({
      ...card,
      statuses: { ...card.statuses, blocked: false },
    }))) as Match['boards'],
  };
  for (const effect of expiring) {
    const beforeExpiration = m.nextEventSequence === match.nextEventSequence ? match : m;
    let afterExpiration = m;
    if (effect.kind === 'buddy-earth-buff' || effect.kind === 'buddy-earth-debuff') {
      const target = effect.targetInstanceId ? findCard(m, effect.targetInstanceId) : undefined;
      if (target) afterExpiration = modify(m, target.instanceId, card => ({
        ...card, powerModifier: card.powerModifier - (effect.amount ?? 0),
        lastEffectNote: 'Earth Squabble expired after two rounds.',
      }));
      // Expiring a temporary buff is not damage for Block Spin.
      afterExpiration = { ...afterExpiration, laneDamage: m.laneDamage };
    } else {
      afterExpiration = modify(m, effect.sourceInstanceId, (card) => ({
        ...card,
        statuses: { ...card.statuses, protected: m.timedEffects.some(active => active.kind === 'salon-protection' && active.targetInstanceId === card.instanceId), blocked: false },
      }));
    }
    afterExpiration = {
      ...afterExpiration,
      timedEffects: afterExpiration.timedEffects.filter((active) => active.id !== effect.id),
    };
    m = addEvent(beforeExpiration, afterExpiration, {
      type: 'expiration', sourceId: effect.sourceInstanceId, owner: effect.owner, targetIds: [effect.sourceInstanceId],
      note: effect.kind === 'buddy-earth-buff' || effect.kind === 'buddy-earth-debuff'
        ? 'Earth Squabble Hands modifier expired after two rounds.'
        : 'Side Eye protection expired at the round boundary.',
      kind: effect.kind === 'buddy-earth-buff' || effect.kind === 'buddy-earth-debuff' ? 'ability' : 'blocked',
    });
  }
  const beforeRoundStart = expiring.length ? m : match;
  m = {
    ...m,
    playerHand: p ? [...m.playerHand, p] : m.playerHand,
    cpuHand: c ? [...m.cpuHand, c] : m.cpuHand,
    playerDrawIndex: m.playerDrawIndex + (p ? 1 : 0),
    cpuDrawIndex: m.cpuDrawIndex + (c ? 1 : 0),
  };
  m = creativeRoundStart(m, creativeTools());
  m = resolveBuddyGrowthAtRoundStart(m);
  m = sproutBuddyBuds(m);
  m = resolveSquabblehouseRoundStart(m);
  const guards = m.boards.flat().filter((card) => abilityCardId(card) === 'wifey' && activeAbility(card));
  for (const guard of guards) {
    m = modify(m, guard.instanceId, (card) => ({ ...card, statuses: { ...card.statuses, protected: true, blocked: false }, lastEffectNote: 'Side Eye refreshed for this round.' }));
    m = { ...m, timedEffects: [...m.timedEffects, {
      id: `wifey:${guard.instanceId}:${next}`, kind: 'wifey-protection', sourceInstanceId: guard.instanceId,
      owner: guard.owner, lane: guard.lane!, startsAtRound: next, expiresAtRound: next + 1, expiration: 'round-start',
    }] };
  }
  m = addEvent(beforeRoundStart, m, {
    type: 'round-start', owner: 'player',
    targetIds: [...guards.map((guard) => guard.instanceId), ...(p ? [p.instanceId] : []), ...(c ? [c.instanceId] : [])],
    timing: guards.length ? 'timed' : 'instant',
    duration: guards.length ? { unit: 'round', startsAtRound: next, expiresAtRound: next + 1, expiration: 'round-start' } : null,
    note: `Round ${next} started.`,
  });
  if (m.boards.flat().some(card => card.cardId === 'squabblehouse-bus-boy'
    && card.lane !== null && activeAbility(card))) {
    // Settle new-round story locks before Bus Boy chooses its automatic route.
    m = applyStoryEffects(m, true);
    m = resolveSquabblehouseBusBoyPatrols(m);
  }
  m = detonateSmileBombs(m);
  m = applyStoryEffects(m);
  m = spawnHandDemarioMushrooms(m, true);
  m = applyStoryEffects(m);
  for (const candidate of m.boards.flat().filter(card => card.cardId === 'redside2')) {
    const red = findCard(m, candidate.instanceId);
    if (!red || red.lane === null || !activeAbility(red) || red.redNightStartRound === undefined) continue;
    const beforeSteal = m;
    const steal = resolveRedNightSteal(m, red);
    if (steal.match === m) continue;
    m = steal.match;
    if (steal.succeeded) m = trainWaveAbility(m, red.instanceId);
    m = addEvent(beforeSteal, m, { type: 'ability', sourceId: red.instanceId, owner: red.owner,
      lane: red.lane, targetIds: steal.targetIds, note: steal.note });
  }
  for (const candidate of m.boards.flat().filter(card => card.cardId === 'blueside3')) {
    const scarf = findCard(m, candidate.instanceId);
    if (!scarf || !activeAbility(scarf) || scarf.lane === null) continue;
    const beforeScarf = m;
    const routed = clearBlueScarfRoute(m, scarf);
    m = routed.match;
    if (routed.moved) m = trainWaveAbility(m, scarf.instanceId);
    m = addEvent(beforeScarf, m, { type: 'ability', sourceId: scarf.instanceId, owner: scarf.owner,
      lane: scarf.lane, targetIds: routed.targetIds, note: routed.note });
  }
  if (!m.districtRuntime) return m;
  m = settleLeaderReactions(applyDistrictRoundStart(m));
  const refreshed = refreshDistrictRound(m);
  const party = m.districtSnapshot!.locations.find(d => d.effect.kind === 'penthouse' && d.effect.changesAtRound === next);
  return addEvent(m, refreshed, { type: 'ability', owner: 'player', kind: 'story',
    note: party ? 'PENTHOUSE: the party starts. Each card here now has +1 Hands instead of the solo bonus.' : `District bonuses refreshed for round ${next}.`,
    lane: party ? m.districtSnapshot!.locations.indexOf(party) as Lane : 0,
  });
}
/**
 * The replay payload accepted by the reward service.  Keep this alongside the
 * structured event stream so the same deterministic rules author both the
 * presentation and the server-verifiable transcript.
 */
export type PlayerMove = {
  cardInstanceId: string | null;
  lane: Lane | null;
  squabble: boolean;
  /** Explicit on new matches; absent only on legacy one-card turns. */
  endTurn?: boolean;
  /** Numeric card choice: Homeless Guy investment, Dice Game wager, or Concert mode. */
  investment?: number;
};
export type TranscriptMove = Omit<PlayerMove, 'lane'> & { lane: number | null };
export const MAX_MATCH_MOVES = 64;

/** Pick a legal teaching move. Spread winning Hands across the districts. */
export function getTutorialPlay(match: Match): { instanceId: string; lane: Lane } | null {
  if (match.phase !== "player") return null;
  let best: { instanceId: string; lane: Lane; value: number } | null = null;
  for (const card of match.playerHand) for (const lane of [0, 1, 2] as const) {
    if (!canAffordSelection(match, "player", card.instanceId, lane)) continue;
    // Keep the mentor for the lesson's final SQUABBLE. Older saved crews
    // without him continue to use the normal legal-move guidance.
    const mentorLesson = match.storyEncounter?.id === 'rookie-road-v2'
      && match.playerHand.some(c => c.cardId === 'drfade');
    if (mentorLesson && ((match.round < 4 && card.cardId === 'drfade')
      || (match.round === 4 && card.cardId !== 'drfade'))) continue;
    const played = playTurnCard(match, "player", card.instanceId, lane, match.round === 4 && !match.squabbleUsed);
    const results = getDistrictResults(revealCpuTurn(pass(played, "player")));
    const value = results.reduce((sum, d) => sum + (d.winner === "player" ? 1000 : 0) + Math.max(-12, Math.min(12, d.player - d.cpu)), 0);
    if (!best || value > best.value) best = { instanceId: card.instanceId, lane, value };
  }
  return best ? { instanceId: best.instanceId, lane: best.lane } : null;
}
/** Build the exact legal transcript taught by the guided tutorial. */
export function createGuidedTutorialTranscript(
  abilityUpgradeSnapshot?: AbilityUpgradeSnapshot,
  districtSnapshot?: DistrictSnapshot,
  encounter?: StoryEncounterSnapshot,
  playerCardIds?: string[],
  playerDeckId = "vibes",
): PlayerMove[] {
  let match = encounter ? createStoryMatch(encounter, playerCardIds ?? deckById(playerDeckId).cards, playerDeckId, abilityUpgradeSnapshot, districtSnapshot) : createMatch(
    "vibes",
    "combo",
    undefined,
    abilityUpgradeSnapshot,
    districtSnapshot,
  );
  const moves: PlayerMove[] = [];
  const roundLimit = getMatchRoundLimit(match);

  for (let round = 1; round <= roundLimit; round += 1) {
    if (round === 1 || round === 2 || round === 4) {
      const candidates = match.playerHand.flatMap((card) =>
        ([0, 1, 2] as const)
          .filter((lane) => canAffordSelection(match, "player", card.instanceId, lane))
          .map((lane) => ({ card, lane })),
      );
      candidates.sort((left, right) =>
        round === 4
          ? right.card.basePower - left.card.basePower || left.lane - right.lane
          : left.card.cost - right.card.cost || left.lane - right.lane,
      );
      const teaching = encounter ? getTutorialPlay(match) : null;
      const selected = teaching ? candidates.find(c => c.card.instanceId === teaching.instanceId && c.lane === teaching.lane) : candidates[0];
      if (!selected) {
        throw new Error(`Tutorial round ${round} needs an affordable play`);
      }
      const squabble = round === 4;
      moves.push({
        cardInstanceId: selected.card.instanceId,
        lane: selected.lane,
        squabble,
        endTurn: false,
      });
      match = playTurnCard(
        match,
        "player",
        selected.card.instanceId,
        selected.lane,
        squabble,
      );
    }

    moves.push({
      cardInstanceId: null,
      lane: null,
      squabble: false,
      endTurn: true,
    });
    match = nextRound(revealCpuTurn(pass(match, "player")));
  }

  if (match.phase !== "complete") {
    throw new Error("Guided tutorial transcript did not complete the match");
  }
  return moves;
}

export function validateTurnRules(moves: readonly TranscriptMove[], version: 1 | 2) {
  if (moves.some(move => version === 2 ? typeof move.endTurn !== 'boolean' : move.endTurn !== undefined)) {
    throw new Error('Transcript does not follow this fade’s turn rules');
  }
}

/** Replay a committed transcript prefix without requiring the match to be complete.
 * This is the only safe way to reconstruct an interrupted online encounter: the
 * serialized client Match is never authoritative. */
export function replayMatchPrefix(initial: Match, moves: readonly TranscriptMove[]): Match {
  const roundLimit = getMatchRoundLimit(initial);
  if (moves.length > MAX_MATCH_MOVES) throw new Error("A transcript may contain at most 64 actions");
  const multiCardTurns = moves.some(move => move.endTurn !== undefined);
  validateTurnRules(moves, multiCardTurns ? 2 : 1);
  let match = initial;
  for (const move of moves) {
    if (match.phase !== 'player') throw new Error('Transcript contains actions after the fade ended');
    if (move.cardInstanceId === null) {
      if (move.lane !== null || move.squabble || move.endTurn === false || (move.investment ?? 0) !== 0) throw new Error('Invalid end turn');
      match = pass(match, 'player');
    } else {
      if (move.lane === null || ![0, 1, 2].includes(move.lane)) throw new Error('Played cards need a valid lane');
      match = multiCardTurns
        ? playTurnCard(match, 'player', move.cardInstanceId, move.lane as Lane, move.squabble, move.investment)
        : playCard(match, 'player', move.cardInstanceId, move.lane as Lane, move.squabble, move.investment);
      if (move.endTurn === true) match = pass(match, 'player');
    }
    if (match.phase === 'cpu-reveal') {
      match = multiCardTurns ? revealCpuTurn(match) : revealCpu(match);
      match = nextRound(match);
    }
  }
  return match;
}
function replayPlayerMoves(initial: Match, moves: readonly TranscriptMove[]): Match {
  const roundLimit = getMatchRoundLimit(initial);
  const roundLabel = roundLimit === DEFAULT_MATCH_ROUND_LIMIT ? "six" : String(roundLimit);
  if (moves.length < roundLimit) throw new Error(`A match needs ${roundLabel} round endings`);
  const match = replayMatchPrefix(initial, moves);
  if (match.phase !== 'complete') throw new Error(`Transcript did not complete ${roundLabel} rounds`);
  return match;
}
export function verifyMatchTranscript(
  playerDeck: string,
  cpuDeck: string,
  moves: TranscriptMove[],
  abilityUpgradeSnapshot?: AbilityUpgradeSnapshot,
  playerCardIds?: readonly string[],
  districtSnapshot?: DistrictSnapshot,
): Match {
  const match = playerCardIds
    ? createMatchFromEngineCards(playerDeck, [...playerCardIds], cpuDeck, [...deckById(cpuDeck).cards], undefined, undefined, abilityUpgradeSnapshot, districtSnapshot)
    : createMatch(playerDeck, cpuDeck, undefined, abilityUpgradeSnapshot, districtSnapshot);
  return replayPlayerMoves(match, moves);
}

export function createStoryMatch(
  snapshot: StoryEncounterSnapshot,
  playerDeck: string | readonly string[],
  playerCardsOrId: readonly string[] | string = "story-player",
  abilityUpgradeSnapshot?: AbilityUpgradeSnapshot,
  districtSnapshot?: DistrictSnapshot,
): Match {
  if (snapshot.enemy.cardIds.length !== DECK_SIZE || new Set(snapshot.enemy.cardIds).size !== DECK_SIZE) {
    throw new Error("Story enemy deck must contain ten unique cards");
  }
  const player = typeof playerDeck === "string"
    ? Array.isArray(playerCardsOrId)
      ? { id: playerDeck, cards: [...playerCardsOrId] }
      : deckById(playerDeck)
    : { id: typeof playerCardsOrId === "string" ? playerCardsOrId : "story-player", cards: [...playerDeck] };
  return createMatchFromEngineCards(
    player.id,
    [...player.cards],
    snapshot.enemy.deckId,
    [...snapshot.enemy.cardIds],
    snapshot,
    undefined,
    abilityUpgradeSnapshot,
    districtSnapshot,
  );
}

export function verifyStoryMatchTranscript(
  snapshot: StoryEncounterSnapshot,
  playerDeck: string | readonly string[],
  playerCardsOrMoves: readonly string[] | TranscriptMove[],
  movesOrDeckId?: TranscriptMove[] | string,
  abilityUpgradeSnapshot?: AbilityUpgradeSnapshot,
  districtSnapshot?: DistrictSnapshot,
): Match {
  const suppliedCards = playerCardsOrMoves.length > 0 && typeof playerCardsOrMoves[0] === "string";
  const moves = (suppliedCards ? movesOrDeckId : playerCardsOrMoves) as TranscriptMove[];
  if (!Array.isArray(moves)) throw new Error("Story fade transcript moves are required");
  const matchCardsOrId = suppliedCards
    ? playerCardsOrMoves as readonly string[]
    : typeof movesOrDeckId === "string" ? movesOrDeckId : "story-player";
  return replayPlayerMoves(createStoryMatch(snapshot, playerDeck, matchCardsOrId, abilityUpgradeSnapshot, districtSnapshot), moves);
}

export type RoundState = {
  round: number; phase: Phase; playerDrawIndex: number; cpuDrawIndex: number;
  squabbleUsed: boolean; plugDiscountLane: Record<Owner, Lane | null>; cheapBuffsUsed: Record<Owner, number>;
  discountTokens: DiscountToken[]; nextDiscountOrder: number; landlordTaxUsed: Record<Owner, Record<Lane, boolean>>;
  sneakerTriggered: Record<Owner, boolean>;
};

export type EventType = 'play' | 'reveal' | 'ability' | 'pass' | 'round-start' | 'expiration' | 'match-complete';

export type EventParticipant = {
  cardInstanceId: string; cardId: string; owner: Owner;
  before: CardEventState | null; after: CardEventState | null;
  departureCause?: 'aura-loss';
};

const roundState = (m: Match): RoundState => ({
  round: m.round,
  phase: m.phase,
  playerDrawIndex: m.playerDrawIndex,
  cpuDrawIndex: m.cpuDrawIndex,
  squabbleUsed: m.squabbleUsed,
  plugDiscountLane: { ...m.plugDiscountLane },
  cheapBuffsUsed: { ...m.cheapBuffsUsed },
  discountTokens: [...(m.discountTokens ?? [])],
  nextDiscountOrder: m.nextDiscountOrder ?? 1,
  landlordTaxUsed: m.landlordTaxUsed ?? { player: { 0: false, 1: false, 2: false }, cpu: { 0: false, 1: false, 2: false } },
  sneakerTriggered: m.sneakerTriggered ?? { player: false, cpu: false },
});

export type EventDuration = { unit: 'round'; startsAtRound: number; expiresAtRound: number; expiration: 'round-start' | 'match-complete' };

const participant = (before: Match, after: Match, id: string): EventParticipant | null => {
  const b = findCard(before, id), a = findCard(after, id);
  const card = a ?? b;
  return card ? { cardInstanceId: card.instanceId, cardId: card.cardId, owner: card.owner, before: cardState(b), after: cardState(a) } : null;
};

const cardState = (card: CardInstance | undefined): CardEventState | null => card ? ({
  cardInstanceId: card.instanceId, cardId: card.cardId, owner: card.owner, lane: card.lane,
  power: getEffectiveCardPower(card), basePower: card.basePower, powerModifier: card.powerModifier,
  ...(card.continuousPower ? { continuousPower: card.continuousPower } : {}),
  moved: card.moved, statuses: { ...card.statuses }, lastEffectNote: card.lastEffectNote,
  ...(card.buddyForm ? { buddyForm: card.buddyForm } : {}),
  ...(card.buddyGrowthAtRound !== undefined ? { buddyGrowthAtRound: card.buddyGrowthAtRound } : {}),
  ...(card.buddyEarthExpiresAtRound !== undefined ? { buddyEarthExpiresAtRound: card.buddyEarthExpiresAtRound } : {}),
  ...(card.buddyBud ? { buddyBud: { ...card.buddyBud } } : {}),
}) : null;

type EventInput = {
  type: EventType; sourceId?: string; owner: Owner; targetIds?: string[]; note: string;
  kind?: EffectKind; timing?: 'instant' | 'timed'; duration?: EventDuration | null; lane?: Lane;
  abilityMetadata?: EffectLogEntry["abilityMetadata"];
};

export type ResourceState = { playerMotion: number; cpuMotion: number };

const resources = (m: Match): ResourceState => ({ playerMotion: m.playerMotion, cpuMotion: m.cpuMotion });

const replayState = (m: Match): ReplayState => JSON.parse(JSON.stringify({
  afterParty: m.afterParty,
  laneDamage: m.laneDamage ?? [],
  diceResult: m.diceResult,
  districtSnapshot: m.districtSnapshot,
  districtRuntime: m.districtRuntime,
  leaderRounds: m.leaderRounds,
  electricPlays: m.electricPlays,
  pendingLeaderReactions: m.pendingLeaderReactions,
  lingeringScents: m.lingeringScents ?? [],
  creativeMarks: m.creativeMarks ?? [],
  districtTraps: m.districtTraps ?? [],
  janitorReversals: m.janitorReversals ?? [],
  lastMovedAlly: m.lastMovedAlly ?? {},
  roundMovedIds: m.roundMovedIds ?? { player: [], cpu: [] },
  cheshireRounds: m.cheshireRounds ?? {},
  squabbleByOwner: m.squabbleByOwner,
  round: m.round,
  phase: m.phase,
  playerHand: m.playerHand,
  cpuHand: m.cpuHand,
  boards: m.boards,
  playerMotion: m.playerMotion,
  cpuMotion: m.cpuMotion,
  nextArrivalOrder: m.nextArrivalOrder ?? nextArrivalOrder(m),
  playerDrawIndex: m.playerDrawIndex,
  cpuDrawIndex: m.cpuDrawIndex,
  squabbleUsed: m.squabbleUsed,
  plugDiscountLane: m.plugDiscountLane,
  cheapBuffsUsed: m.cheapBuffsUsed,
  discountTokens: m.discountTokens ?? [],
  blueNextBonus: m.blueNextBonus ?? {},
  nextDiscountOrder: m.nextDiscountOrder ?? 1,
  landlordTaxUsed: m.landlordTaxUsed ?? { player: { 0: false, 1: false, 2: false }, cpu: { 0: false, 1: false, 2: false } },
  sneakerTriggered: m.sneakerTriggered ?? { player: false, cpu: false },
  timedEffects: m.timedEffects,
  storyRuntime: m.storyRuntime,
  abilityUpgradeSnapshot: m.abilityUpgradeSnapshot,
  squabblehouseRevealHistory: m.squabblehouseRevealHistory ?? [],
})) as ReplayState;

export type ScoreState = { lane: Lane; player: number; cpu: number };

const addEvent = (before: Match, after: Match, input: EventInput): Match => {
  after = reconcileContinuousPower(after);
  const neutralDepartures = after[CONTINUOUS_POWER_DEPARTURES] ?? [];
  after = clearContinuousPowerDepartures(after);
  if (
    before[SUPPRESS_PRESENTATION_EVENTS] ||
    after[SUPPRESS_PRESENTATION_EVENTS]
  ) {
    return {
      ...after,
      [SUPPRESS_PRESENTATION_EVENTS]: true,
      nextEventSequence: after.nextEventSequence + 1,
      effectLog: [],
    };
  }
  const neutralById = new Map(neutralDepartures.map(card => [card.instanceId, card]));
  const eventParticipant = (id: string): EventParticipant | null => {
    const departure = neutralById.get(id);
    return departure
      ? { cardInstanceId: departure.instanceId, cardId: departure.cardId, owner: departure.owner,
        before: cardState(departure), after: null, departureCause: 'aura-loss' }
      : participant(before, after, id);
  };
  const source = input.sourceId ? eventParticipant(input.sourceId) : null;
  const targetIds = [...new Set([...(input.targetIds ?? []), ...neutralDepartures.map(card => card.instanceId)])]
    .filter((id) => id !== input.sourceId);
  const sourceCard = input.sourceId ? findCard(after, input.sourceId) ?? findCard(before, input.sourceId) : undefined;
  const neutralIds = new Set(neutralDepartures.map(card => card.instanceId));
  const event: EffectLogEntry = {
    sequence: after.nextEventSequence,
    round: after.round,
    type: input.type,
    timing: input.timing ?? 'instant',
    duration: input.duration ?? null,
    source,
    targets: targetIds.map(eventParticipant).filter((x): x is EventParticipant => x !== null),
    scores: { before: scores(before), after: scores(after) },
    resources: { before: resources(before), after: resources(after) },
    state: { before: roundState(before), after: roundState(after) },
    replay: { before: replayState(before), after: replayState(after) },
    cardInstanceId: sourceCard?.instanceId ?? input.type,
    cardId: sourceCard?.cardId ?? input.type,
    owner: sourceCard?.owner ?? input.owner,
    lane: input.lane ?? sourceCard?.lane ?? 0,
    kind: input.kind ?? 'ability',
    note: input.note
      + targetIds.filter(id => findCard(before, id) && !findCard(after, id) && !neutralIds.has(id))
        .map(id => ` ${findCard(before, id)!.name} was destroyed.`).join('')
      + neutralDepartures.map(card => ` ${card.name} was destroyed when its Manager aura expired.`).join(''),
    ...(input.abilityMetadata ? { abilityMetadata: input.abilityMetadata } : {}),
  };
  return { ...after, nextEventSequence: after.nextEventSequence + 1, effectLog: [...after.effectLog, event] };
};

export type CardEventState = {
  cardInstanceId: string; cardId: string; owner: Owner; lane: Lane | null;
  power: number; basePower: number; powerModifier: number; moved: boolean;
  continuousPower?: number;
  statuses: Statuses; lastEffectNote: string;
  buddyForm?: 'earth' | 'squabble-earth';
  buddyGrowthAtRound?: number;
  buddyEarthExpiresAtRound?: number;
  buddyBud?: { readonly sourceInstanceId: string; readonly sproutsAtRound: number; readonly sprouted: boolean };
};

const scores = (m: Match): ScoreState[] => getDistrictResults(m).map(({ lane: district, player, cpu }) => ({ lane: district, player, cpu }));

function blockbusterTools(): BlockbusterTools {
  return { modify, protect: grantProtection, enemyMove: forceEnemyMove, hit: targetEnemyPowerReduction, reduce: reduceHands, move, cleanse: cleanseAlly,
    status: (m, source, target, status, note) => hostileEffect(m, source, target, (state, actual) => modify(state, actual.instanceId,
      c => ({ ...c, statuses: { ...c.statuses, [status]: true }, lastEffectNote: note })), false, false, true),
    burn: (m, source, target) => targetEnemyBurnAndPowerReduction(m, source, target, 1, 2, 'Chain Reaction: -2 Hands and 1 Burn.'),
    create: createCardInstance, locked: getStoryLockedLanes, power: getEffectiveCardPower, rawPower: rawCombatPower,
    sync: syncContinuousPower, random: seededIndex };
}
function applyBurntPlates(match: Match): Match {
  let m = match;
  for (const plate of match.boards.flat().filter(c => c.cardId === 'burnt-plate')) {
    const crew = m.boards[plate.lane!].filter(c => !c.hazard && (c.kind ?? 'character') === 'character' && c.owner === plate.owner);
    m = { ...m, boards: m.boards.map(cs => cs.filter(c => c.instanceId !== plate.instanceId)) as Match['boards'] };
    if (!crew.length) continue;
    const target = crew[seededIndex(`${plate.instanceId}:${m.round}:burn`,crew.length)];
    const before = m;
    if (!target.statuses.uncounterable) m = modify(m,target.instanceId,c => ({ ...c,statuses:{...c.statuses,burnStacks:c.statuses.burnStacks+1},lastEffectNote:'Burnt Plate: +1 Burn.' }));
    m = addEvent(before,m,{type:'ability',sourceId:plate.instanceId,owner:plate.owner,lane:plate.lane!,targetIds:[target.instanceId],kind:'fire',note:'Burnt Plate: one 1-Burn penalty; plate cleared.'});
  }
  return m;
}

function creativeTools(): CreativeTools {
  return {
    trim: (m, source, target, amount) =>
      hostileEffect(
        m,
        { ...source, cardId: "thefeds", copiedAbilityCardId: undefined },
        target,
        (state, actual) =>
          modifyWithoutDamage(state, actual, (c) => ({
            ...c,
            powerModifier:
              c.powerModifier - Math.min(amount, Math.max(0, c.powerModifier)),
            lastEffectNote: source.ability + ": bonus Hands removed.",
          })),
        false,
        false,
        true,
      ),
    power: getEffectiveCardPower,
    modify,
    protect: grantProtection,
    hit: targetEnemyPowerReduction,
    status: (m, source, target, key, note) =>
      hostileEffect(
        m,
        source,
        target,
        (state, actual) =>
          queueDisruptionReactions(
            state,
            modify(state, actual.instanceId, (c) => ({
              ...c,
              statuses: { ...c.statuses, [key]: true },
              lastEffectNote: note,
            })),
            source,
            actual.instanceId,
          ),
        false,
        false,
        true,
      ),
    burn: applyBurn,
    cleanse: (m, id) =>
      cleanseAlly(m, id, (c) => ({
        ...c,
        statuses: cleanseStatuses(c.statuses),
      })),
    move,
    movePair: creativeMovePair,
    enemyMove: forceEnemyMove,
    canMove: canMoveTo,
    score: (m, owner, lane) =>
      getLaneScoreForMatch(m, inLane(m, owner, lane), lane, owner),
    reveal: (m, source) => resolveAbility(m, source),
    train: trainCreativeAbility,
    refund: refundMotion,
    roundLimit: getMatchRoundLimit,
    disruption: queueDisruptionReactions,
    event: (before, after, source, targets, note) =>
      addEvent(
        after.effectLog.length > before.effectLog.length ? after : before,
        after,
        {
          type: "ability",
          kind:
            source.type === "Fire"
              ? "fire"
              : source.type === "Water"
                ? "water"
                : "ability",
          sourceId: source.instanceId,
          owner: source.owner,
          lane: source.lane ?? 0,
          targetIds: targets,
          note,
        },
      ),
  };
}
function trainCreativeAbility(m: Match, id: string): Match {
  const source = findCard(m, id);
  if (
    !source ||
    !CREATIVE_KITS[source.cardId] ||
    source.lane === null ||
    source.creativeUsed?.training
  )
    return m;
  m = modify(m, id, (c) => ({
    ...c,
    creativeUsed: { ...c.creativeUsed, training: true },
  }));
  for (const upgrade of snapshotUpgradesForCard(
    m.abilityUpgradeSnapshot,
    source.owner,
    source.cardId,
  )) {
    const e = upgrade.effect;
    const target =
      e.kind === "self-power"
        ? findCard(m, id)
        : lowest(
            m.boards
              .flat()
              .filter(
                (c) =>
                  !c.hazard &&
                  c.instanceId !== id &&
                  c.owner ===
                    (e.target === "friendly"
                      ? source.owner
                      : source.owner === "player"
                        ? "cpu"
                        : "player") &&
                  c.lane === source.lane,
              ),
          );
    if (!target) continue;
    const before = m;
    m =
      e.amount < 0
        ? targetEnemyPowerReduction(m, source, target, e.amount, upgrade.name)
        : modify(m, target.instanceId, (c) => ({
            ...c,
            powerModifier: c.powerModifier + e.amount,
          }));
    m = addEvent(before, m, {
      type: "ability",
      sourceId: id,
      owner: source.owner,
      targetIds: [target.instanceId],
      note: upgrade.name + ": once-per-match training.",
      abilityMetadata: {
        upgradeId: upgrade.id,
        upgradeName: upgrade.name,
        sourceCardId: source.cardId,
        sourceInstanceId: id,
        targetInstanceIds: [target.instanceId],
        result: "applied",
      },
    });
  }
  return m;
}

function creativeMovePair(
  m: Match,
  first: CardInstance,
  second: CardInstance,
  destination: Lane,
  note: string,
): Match {
  if (
    first.instanceId === second.instanceId ||
    first.owner !== second.owner ||
    !moveRouteLegal(m, first, destination) ||
    !moveRouteLegal(m, second, destination) ||
    m.boards[destination].filter((c) => c.owner === first.owner).length > 2
  )
    return m;
  const before = m;
  const firstDeparture = openTabDeparture(m, first);
  if (firstDeparture.stopped) return firstDeparture.match;
  const liveSecond = findCard(firstDeparture.match, second.instanceId);
  if (!liveSecond) return firstDeparture.match;
  const secondDeparture = openTabDeparture(firstDeparture.match, liveSecond);
  if (secondDeparture.stopped) return secondDeparture.match;
  m = move(secondDeparture.match, first, destination, note, true, false, true);
  const passenger = findCard(m, second.instanceId);
  if (passenger) m = move(m, passenger, destination, note, true, false, true);
  for (const original of [first, second]) {
    m = fairytaleDeparture(m, original);
    m = fairytaleArrival(m, original.instanceId, findCard(m, original.instanceId)?.lane === destination);
    m = applyScentEntry(m, original.instanceId);
    m = homecomingArrival(creativeMoved(before, m, original.instanceId, creativeTools()), original.instanceId, homecomingTools());
  }
  return m;
}


function homecomingTools(): HomecomingTools {
  return { ...creativeTools(), train: trainWaveAbility,
    returnAlly: (m, source, target) => returnToHand(m, source, target, true),
    tow: (m, source, target) => hostileEffect(m, { ...source, cardId: 'thefeds', copiedAbilityCardId: undefined }, target, (state, actual) => {
      if (source.lane === null || !canMoveTo(state, actual, source.lane)
        || state.boards[source.lane].filter(c => !c.hazard && c.owner === actual.owner).length >= 4) return state;
      let result = forceMoveUnshielded(state, actual, source.lane);
      const arrived = findCard(result, actual.instanceId);
      if (!arrived || arrived.lane !== source.lane) return result;
      const amount = Math.min(3, Math.max(0, arrived.powerModifier));
      const recipient = lowest(inLane(result, source.owner, source.lane).filter(c => c.kind !== 'support'));
      if (!amount || !recipient) return result;
      result = modifyWithoutDamage(result, arrived, c => ({ ...c, powerModifier: c.powerModifier - amount,
        lastEffectNote: `Tow & Collect: repossessed ${amount} bonus Hands.` }));
      return modify(result, recipient.instanceId, c => ({ ...c, powerModifier: c.powerModifier + amount,
        lastEffectNote: `Tow & Collect: received ${amount} repossessed Hands.` }));
    }, false, false, true),
  };
}

