}
const screenplay = chapterOneDialogue as Record<string, Partial<Record<'pre' | 'post' | 'main', StoryDialogueLine[]>>>;
export const storyDialogueToken = (nodeId: string, section: 'pre' | 'post' | 'main', index: number) => {
  if (!hasSeasonOneRewrite(nodeId)) return `${nodeId}:script-v3:${section}:${index}`;
  const revision = seasonOneRewriteRevision(nodeId);
  if (!revision) throw new Error(`Season One screenplay has no read revision for ${nodeId}`);
  return `${nodeId}:script-${revision}:${section}:${index}`;
};
const storyPayoutContractKey = (nodeId: string, reward: "clout" | "ticket") =>
  `story-payout-contract:v1:${nodeId}:${reward}`;
function applyStoryPayoutContract(chapters: readonly StoryChapter[]): StoryChapter[] {
  return chapters.map((chapter) => {
    const finale = [...chapter.nodes].reverse().find((node) => !node.optional);
    return {
      ...chapter,
      nodes: chapter.nodes.map((node) => {
        const isFinale = node.id === finale?.id;
        const isBoss = node.kind === "battle" && (node.battleType === "boss" || node.battleType === "mini-boss");
        const cloutTarget = Math.max(
          100,
          isBoss ? 200 : 0,
          isFinale ? 250 : 0,
          node.rewards
            .filter((reward) => reward.kind === "currency" && reward.id === "clout")
            .reduce((sum, reward) => sum + reward.amount, 0),
        );
        const ticketTotal = node.rewards
          .filter((reward) => reward.kind === "pack-ticket" && reward.id === "street-pack-ticket")
          .reduce((sum, reward) => sum + reward.amount, 0);
        const ticketTarget = isFinale ? Math.max(10, ticketTotal) : Math.max(1, ticketTotal);
        const cloutTotal = node.rewards
          .filter((reward) => reward.kind === "currency" && reward.id === "clout")
          .reduce((sum, reward) => sum + reward.amount, 0);
        const additions: StoryReward[] = [];
        if (cloutTarget > cloutTotal) {
          additions.push({
            kind: "currency",
            id: "clout",
            amount: cloutTarget - cloutTotal,
            claimKey: storyPayoutContractKey(node.id, "clout"),
          });
        }
        if (ticketTarget > ticketTotal) {
          additions.push({
            kind: "pack-ticket",
            id: "street-pack-ticket",
            amount: ticketTarget - ticketTotal,
            claimKey: storyPayoutContractKey(node.id, "ticket"),
          });
        }
        return additions.length ? { ...node, rewards: [...node.rewards, ...additions] } : node;
